@keyframes rs-anim-toast-in{from{opacity:0}to{opacity:1}}
.rs-toasts{position:fixed;bottom:20px;inset-inline-end:20px;z-index:var(--z-toast);display:flex;flex-direction:column;align-items:flex-end;gap:8px}
@media (max-width: 640px){.rs-toasts{bottom:0;inset-inline-end:0;inset-inline-start:0;align-items:stretch;gap:0}}
.rs-toast{display:flex;align-items:flex-start;gap:10px;background-color:var(--bg);border-width:1px;border-style:solid;border-color:var(--divider);border-radius:var(--radius);box-shadow:0 8px 24px rgba(0,0,0,0.06);padding-top:10px;padding-inline:14px;padding-bottom:10px;max-width:340px;animation-name:rs-anim-toast-in;animation-duration:var(--duration-confirm);animation-timing-function:var(--ease)}
@media (max-width: 640px){.rs-toast{border-radius:0;box-shadow:none;padding-top:16px;padding-inline:20px;padding-bottom:calc(16px + env(safe-area-inset-bottom, 0px));max-width:none;width:100%}}
@media (prefers-reduced-motion: reduce){.rs-toast{animation-name:none}}
.rs-toast-title{display:block;font-size:13px;font-weight:600;letter-spacing:-0.01em;color:var(--text)}
@media (max-width: 640px){.rs-toast-title{font-size:16px}}
.rs-toast-body{font-size:12.5px;line-height:1.5;letter-spacing:-0.01em;color:var(--text-secondary);margin-top:1px;margin-bottom:0;margin-inline:0}
@media (max-width: 640px){.rs-toast-body{font-size:15px;margin-top:4px}}
.rs-toast-close{box-sizing:border-box;display:inline-flex;align-items:center;justify-content:center;flex-shrink:0;margin-inline-start:auto;margin-top:-4px;margin-inline-end:-6px;width:28px;height:28px;padding:0;border-width:0;border-radius:var(--radius-sm);background-color:transparent;color:var(--text);cursor:pointer}
.rs-toast-close:hover{background-color:var(--divider)}
.rs-toast-close:focus-visible{outline-width:2px;outline-style:solid;outline-color:var(--text);outline-offset:2px}
@media (max-width: 640px){.rs-toast-close{margin-top:-10px;margin-inline-end:-12px;width:var(--hit);height:var(--hit)}}

